insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('3eedda97-43cc-433a-95d4-4bf4878958cd', 'ja', '彼女は会話に乗っていて、エネルギーも高いままです。流れを保てる、前提に立った提案はどれですか？', '["「これは、またやりましょう。LINE、交換しましょう」", "「また会うことに、興味はありますか？」", "「いつか遊びに行くのは、ありですか？」", "「もしかしたら、会ったほうがいいかもしれませんね？」"]'::jsonb, '彼女の関心を確かなものとして扱い、予定をまっすぐ提案しましょう。')
