insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('4533a8d2-717d-49b4-b4a9-c89b28985777', 'ja', '彼女が「ちょうど台湾旅行から帰ってきたところなんです」と言います。次に何を言えますか？', '["自分の旅行の経験を話す", "「台湾で一番良かったのは、何でしたか？」と尋ねる", "話題を変えて、どこに住んでいるかを尋ねる", "旅行していることを褒める"]'::jsonb, '糸口をたどると、彼女の話した内容を広げて、会話を自然に深められます。')
