insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('48b2d089-1b51-4e26-9f2f-517c02891e1b', 'ja', '言葉を使わずに、関わっていることを伝える行動は、どれですか？', '["彼女が話しているあいだ、体を向けていること", "ずっと変わらない、どちらともつかない表情", "自然なアイコンタクト", "大事なところでの、さりげないうなずき"]'::jsonb, '体の向き、アイコンタクト、そして反応する動きが、その場にいることを伝えます。')
