insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('497c00d6-116b-4bf7-9ccf-9fdbef04ef82', 'ja', '彼女が家族について短く答え、エネルギーが下がります。次に何ができますか？', '["家族について、もうひとつ質問する", "「ところで、その料理、味はどうですか？」と、軽く切り替える", "気まずい瞬間について謝る", "なぜ短く答えたのかを尋ねる"]'::jsonb, '落ち着いて当たり障りのない話題へ向きを変え、プレッシャーをかけずに流れを整え直しましょう。')
