insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('4e01d376-3513-4958-b45f-3cbac7198e67', 'ja', '彼女のこれからのポルトガル旅行について、楽しく話せました。そろそろ立ち去る時間です。何と言えますか？', '["「お話しできてよかったです。よい一日を」", "「ポルトガル、最高ですね。どうだったか、ぜひ聞かせてくださいね」", "「行くときは、気をつけて」"]'::jsonb, '具体的な話題にもう一度触れて終えると、つながりが続き、自然にまた連絡できます。')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('4e138ced-bcd3-4f4b-9394-d046b4bd81e7', 'ja', '彼女が、こちらのすすめたカフェに行ってみたいと話します。気軽で良い次へのつなげ方は、どれですか？', '["「今週、一緒に行きましょう。土曜日は空いていますか？」", "「住所を送りますね。LINE、教えてもらえますか？」", "「行ってみて良かったら、教えてくださいね」"]'::jsonb, 'プレッシャーの少ない誘いは、警戒を下げます。「はい」が自然に感じられるよう、誘いは小さくしておきましょう。')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('52c57688-6476-42cc-9677-4cb5e66512fd', 'ja', '彼女が「前の恋愛は、どうして終わったんですか？」と尋ねます。最も地に足のついた返しは、どれですか？', '["「彼女にひどく傷つけられて、まだ引きずっているんです」", "「ひどい関係で、本当にぼろぼろになりました」", "「求めるものが違っていたんです。おかげで、自分が何を大切にしたいのかが、前よりわかりました」"]'::jsonb, 'この返しは、現実を認めながら、自分なりの見方を示しています。心配ではなく、好奇心を招きます。')
