insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('6309d2eb-7004-43f3-99ec-c276acb5ec61', 'ja', '彼女はしっかり目を合わせ、さらに質問をしてきます。これは何を示していますか？', '["気が散っていて、会話を終えたがっている", "まず、もっと雑談が必要", "礼儀正しくしているだけで、関心はない", "気持ちが入っていて、次につなげる機が熟している"]'::jsonb, '積極的な好奇心と好意的なボディランゲージは、次につなげる機が熟したことを示しています。')
