insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('674acf71-26d4-428e-aa33-571e27f0d7d7', 'ja', '糸口をたどることが、話題を飛び移るよりも自然に感じられるのは、なぜですか？', '["友人同士の実際の話し方と同じだから", "会話が行き当たりばったりにならず、積み重なっていくから", "話した内容に応えてもらえるので、彼女が「聞いてもらえた」と感じるから", "会話が積み重なり、彼女が「聞いてもらえた」と感じるから"]'::jsonb, '糸口をたどると、流れが生まれます。ひとつひとつの返しが、前の返しの上に積み重なっていきます。')
