insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('87339858-15ab-4a2b-89af-d6a42cafac7a', 'ja', '受け止める言葉は、何をもたらしますか？', '["彼女の言葉が、本当に届いたことを示す", "より本音のやり取りが生まれる余地をつくる", "自信と、感情への気づきを示す", "「わかってもらえた」と感じたまま、彼女をその瞬間にとどめる"]'::jsonb, '彼女の言葉を受け止めることは、聞いていたことを示し、より深い話を招きます。')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('97b34e22-5615-4aa3-bf23-73f5718f67c6', 'ja', 'エピソードを、行き止まりではなく、つながりに変えるのに役立つ行動は、どれですか？', '["結果がどれほどすごかったかで締めくくること", "彼女自身は、その状況をどう感じるかを尋ねること", "彼女がすでに話してくれたことに、エピソードを結びつけること"]'::jsonb, 'エピソードは、彼女の世界を会話に招き入れるとき、つながりを生みます。')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('97e7b932-511e-48e1-bf8b-9b0e49bd18f9', 'ja', '彼女が話している最中に、自分が返事を考えていることに気づきます。どうするべきですか？', '["手早く考え終えてから、彼女の話にもう一度集中する", "考えるのをやめて、今すぐ彼女の言葉に注意を戻す", "集中が切れたので、最後の部分をもう一度話してもらう"]'::jsonb, '注意がそれたことに気づいたら、すぐに彼女の言葉とトーンに注意を戻しましょう。')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('998825a4-01bc-40bc-9219-b9e8a227feb8', 'ja', '違う意見を口にしたあと、緊張を感じます。最もすっきりした切り替え方は、どれですか？', '["トーンをやわらげて、彼女の経験について尋ねる", "さらに根拠を出して、もっと押す", "意見が違ったことを謝る"]'::jsonb, '証明することから、理解することへ切り替えましょう。代わりに、彼女の経験を聞かせてもらいます。')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('9a3ada69-efcb-4e14-96d0-7d4c087e2d2a', 'ja', '観察や自分のひと言は、主に会話に何をもたらしますか？', '["やり取りを釣り合わせる", "自分の見方を明かす", "彼女に、答えることを求める"]'::jsonb, 'やり取りを、分かち合っている、温かいものに感じさせます。')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('9b82f398-1878-449a-baf9-24e1e9ec6c0d', 'ja', '整理のついた話は、なぜつながりを生むのですか？', '["自己認識と、人としての成長を示すから", "彼女に気持ちの重荷を負わせずに、弱さを見せるから", "助けなければという義務感を生まずに、親しさを招くから", "上のすべて"]'::jsonb, '整理のついた経験は、世話を焼いてもらうことではなく、つながりを招きます。')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('9bb0ed54-392a-4aab-9aed-715508c1df96', 'ja', 'ある映画についての彼女の見方に、同意できません。彼女は熱を込めて話しています。次に何ができますか？', '["なぜ彼女の意見に欠陥があるのかを説明する", "「面白い見方ですね。どうしてそんなに好きなんですか？」と言う", "波風を立てないために、同意するふりをする", "すぐに新しい話題に移る"]'::jsonb, '違いがあってもつながり続けるために、彼女の熱意に好奇心を示しましょう。')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('9d4b7485-9598-45ab-9df1-95a6de8dbd91', 'ja', '彼女が「今週は、毎晩遅くまで働いていて」と言います。次に何を言えますか？', '["「お仕事は何をしているんですか？」", "「それは、今夜出かける資格が十分にありますね」", "「何時間くらい働いているんですか？」", "「疲れていますか？」"]'::jsonb, '自分のひと言は、会話に何かを差し出し、プレッシャーをかけずに、彼女が話すのを招きます。')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('9f096c93-c6af-4940-a92a-503d7c7f4a16', 'ja', '彼女が、新しい仕事で苦労していると話します。こちらも自分の経験を話します。次はどうしますか？', '["「自分もそうでした。それはそうと…」", "「そちらは、ここまで慣れるのはどうですか？」", "「具体的には、どんなお仕事なんですか？」"]'::jsonb, '彼女の今の状況につなげて、彼女の見方を招き、打ち解けた空気を深めましょう。')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('9f811f6d-ea33-440c-a2f7-4e4f2eab4134', 'ja', '彼女が、仕事でストレスを感じていると言います。前向きな結びつきを生む返しは、どれですか？', '["「それは大変ですね。仕事って、きついですよね」", "「時間の使い方を、もっと工夫してみたらどうですか」", "「最近は、みんなストレスを抱えていますよね」", "「それが終わったら、一番楽しみにしていることは何ですか？」"]'::jsonb, 'この返しは、彼女の気持ちの状態を、ストレスから、安心と楽しみへとやさしく切り替えます。')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('a3852cf6-c43a-47f6-95c6-432c2afa408f', 'ja', '一緒に歩いていて、会話がゆっくりになります。すっきり整え直せていることを示すのは、どれですか？', '["向きを変える前の、ゆったりした間", "次々に話題を変えること", "退屈かどうかを尋ねること"]'::jsonb, '落ち着きは、速さよりも、自信を伝えます。')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('a567d0df-afca-4f4d-bed2-fa676a9cd119', 'ja', 'こちらが話しているあいだ、彼女はうなずいていますが、あまり話を足してきません。一番良い調整はどれですか？', '["自分の話を、力強く締めくくる", "言い切るために、ペースを上げる", "間を置いて、彼女の見方を聞かせてもらう", "唐突に話題を変える"]'::jsonb, '様子を確かめることで、バランスが戻り、彼女がまた会話に加わりやすくなります。')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('a6a5fa05-f1d7-453b-b228-4c8e34485599', 'ja', '質問しかしないと、何が起こりますか？', '["話の中身を出す負担を、すべて彼女が負う", "会話が、つながりではなく、面接のように感じられる", "答え続けることに、彼女が疲れてしまう", "上のすべて"]'::jsonb, '質問が多すぎると、情報をもらうばかりの構図になり、彼女が会話を背負うことになります。')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('a734d277-baef-4344-8dd3-962cd62d6ac3', 'ja', '自分と前向きな感情を結びつけてもらうことは、なぜ大切なのですか？', '["感情は、こちらとのより強い結びつきを生むから", "前向きな気持ちは、もっと一緒に過ごしたいと彼女に思わせるから", "後ろ向きな感情は、いつでも惹かれる気持ちを高めるから"]'::jsonb, '惹かれる気持ちは、話の内容だけでなく、一緒にいて彼女がどう感じるかの上に育ちます。')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('a89cc880-19f7-430e-b699-51926d19b98b', 'ja', '彼女が、自分とは違う意見を話します。つながりを最もよく保てる返しは、どれですか？', '["なぜ彼女の見方に欠陥があるのかを説明すること", "緊張を避けるために、同意すること", "すぐに話題を変えること", "彼女の見方を受け止め、どうしてそう考えるようになったのかを尋ねること"]'::jsonb, '好奇心は、やり取りを、競い合いではなく、協力し合うものに保ちます。')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('a9785ffd-0cfe-4181-b029-10a0c6cc6131', 'ja', '「IT系の仕事をしているんですが、実は週末は絵を描いているんです」。糸口をたどる返しとして一番良いのは、どれですか？', '["「ITとアートですか。面白い組み合わせですね。どうしてそうなったんですか？」", "「へえ、いいですね。ITでは、どんなお仕事をしているんですか？」", "「絵ですか！素敵ですね。どんな絵を描くんですか？」"]'::jsonb, '両方の糸口を組み合わせ、すべて聞いていたことを示し、彼女のエピソードへの入り口をつくっています。')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('aa6e8752-217b-4419-a60b-1e74d05c3e39', 'ja', '彼女が面白いエピソードを話して、笑います。こちらのボディランゲージは、どうあるべきですか？', '["完全に動かず、どちらともつかないままでいる", "オチのところで、ほほえんでうなずく", "前のめりに見えないように、目をそらす", "腕を組んで、後ろにもたれる"]'::jsonb, '表情の反応で彼女のエネルギーに合わせることは、本当に関わっていることを示します。')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('ab4ba3e7-8e8e-4347-a113-cdb95d15d251', 'ja', '会話のリズムを崩しがちな行動は、どれですか？', '["途切れなく続く、長いエピソード", "続きのない、短い返事", "短く話して、そのあと余白を残すこと", "話し終えたあと、様子を確かめること"]'::jsonb, '独占することも、引っ込むことも、リズムのバランスを崩します。')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('add28003-e846-44f9-b448-3449baa804b7', 'ja', '彼女が、こちらの意見に反論します。健全な反応ができていることを示すのは、どれですか？', '["リラックスしたまま、関わり続けること", "自分の正しさを証明するために、例を並べること", "相手の強さに合わせて、声を大きくすること", "その話題から引っ込むこと"]'::jsonb, 'リラックスしたままでいることは、意見の違いに脅かされていないことを示します。')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('af3e39be-381e-451e-aa88-6cebba413dad', 'ja', '受け止める言葉の例は、どれですか？', '["「それは大変ですね」", "「それが大切な理由、わかります」", "「どうしてそうなったんですか？」", "「それはつらかったでしょうね」"]'::jsonb, '短く受け止めるひと言は、彼女の言葉に重みがあることを示します。')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('b14823ef-b8ce-4062-8fcb-4cfcf41fc931', 'ja', '意見の違いが問題になるのは、どんなときですか？', '["つながり続けることよりも、正しくあることのほうが大事になったとき", "意見が違いすぎて、共通点が見つからないとき", "信頼が築かれる前の、早すぎる段階で起きたとき"]'::jsonb, '理解することよりも、正しくあることのほうが大事になったとき、つながりは切れます。')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('b284a2c4-70e8-4c60-91c5-92cbc5e68edf', 'ja', '彼女が、趣味の話をしながら表情を輝かせます。こちらは立ち去らなければなりません。最後のひと言の手がかりになるのは、何ですか？', '["手際よく終えること", "プレッシャーを避けること", "短くすること", "彼女を生き生きとさせた話題に触れること"]'::jsonb, '彼女にとって大切だった話題で終えると、やり取りの気持ちのトーンが保たれます。')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('b5ac4b83-5b84-4914-8cdf-cbba23aa7ff4', 'ja', '好きなラーメン屋について、軽く楽しい会話をしています。どう次につなげられますか？', '["「今度デートしましょう。夕食にお誘いしてもいいですか？」", "「さっき話したラーメン屋、送りますね。LINE、教えてもらえますか？」", "「近いうちに遊びましょう。いつ空いていますか？」"]'::jsonb, '小さくて気軽な次の一歩は、その場のトーンに合っていて、自然に感じられます。')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('b7fd7470-ddb6-4107-9390-97cff5fc0696', 'ja', 'ありきたりな別れのあいさつは、なぜ良い会話のあとの流れを断ち切ってしまうのですか？', '["あとで送るメッセージが、唐突に感じられるようになるから", "覚えておいたり、また連絡したりするための具体的な手がかりを、彼女に何も残さないから", "しっかり聞いていたことを示すから"]'::jsonb, 'ありきたりな別れ方は、次への橋をかける代わりに、やり取りを完全に閉じてしまいます。')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('bac16dba-494e-42a6-85ef-76041bd6b867', 'ja', '返すために聞くことは、なぜ本物のつながりを妨げるのですか？', '["意識が、彼女の言葉ではなく、自分の次のひと言に向くから", "言外のメッセージや、気持ちの手がかりを聞き逃すから", "返しがありきたりで、かみ合わないものに感じられるから", "その瞬間に、しっかりいることを示すから"]'::jsonb, '返事を考えると、意識が内側に向き、本当には聞いていないことが伝わります。')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('bb4ac1da-dc29-41e3-a551-022813ad2ba6', 'ja', '彼女が、今週末は空いていると言います。一番合う、前提に立った提案はどれですか？', '["「夕食でもどうですか？」", "「会ったほうがいいと思いますか？」", "「じゃあ、そのとき会いましょう。LINE、交換しましょう」", "「もし興味があれば、夕食とか…？」"]'::jsonb, '予定は決まったものとして、自信を持って、具体的な段取りに進みましょう。')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('bf592d93-816d-437d-bf97-761e412be0fa', 'ja', '言外のメッセージに応えることは、なぜつながりを生むのですか？', '["言葉どおりの意味の先まで聞いていることを示すから", "会話を表面的なままに保つから", "彼女に、本当に理解されたと感じさせるから", "彼女の言葉の裏にある気持ちを受け止めるから"]'::jsonb, '言外のメッセージは、本当に伝えたいことを明かします。そこに応えることで、波長が合っていきます。')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('c46c2263-5933-4984-8b1a-1cb44756f991', 'ja', '順を追って話す長いエピソードは、なぜ相手の関心を失いやすいのですか？', '["不誠実に感じられるから", "弱さを見せすぎているから", "自信のなさを示すから", "話を追うのに、労力がかかりすぎるから"]'::jsonb, '聞き手が話を追うのに苦労すると、気持ちのつながりは弱まります。')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('c6ab667b-89c1-40bf-81ce-fc391a31cf88', 'ja', '会話の序盤は、なぜ軽いままにしておくべきなのですか？', '["重い話題には、信頼が育つ時間が必要だから", "整理のついていない話は、偏りを生むから", "整理のついた話は、自然な親しさを招くから", "最初から深いほうが、いつでも良いから"]'::jsonb, '軽やかな土台があれば、つながりは安心して育っていきます。')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('c7773b16-20a8-4e4f-b8d5-ce0164ce4e7a', 'ja', '良い会話のあとでも、大きな誘いは、なぜためらいを生むことが多いのですか？', '["かかっているものを、急に大きくするから", "練習してきたように感じられるから", "必死に聞こえるから", "惹かれる気持ちを弱めるから"]'::jsonb, 'かかっているものが急に大きくなると、人は本能的に身を引きます。')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('c8c65a67-7bdf-4ffa-95d7-4d6f1b019a36', 'ja', '質問を3つ続けたところ、彼女は答えてくれますが、エネルギーは平板に感じられます。次にどうするべきですか？', '["関心を取り戻すために、もっと引き込む質問をする", "彼女がもっと熱を込めて話せる、別の話題に切り替える", "やり取りの釣り合いを取るために、自分のひと言や観察を口にする"]'::jsonb, '観察は、答える負担をかけずに、彼女に「返せるもの」を渡します。')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('c9c21217-6720-474d-becb-eea9a3d28503', 'ja', '彼女が「心理学を学んだんですが、結局プロダクトデザインの仕事に就いたんです」と言います。使える糸口は、どれですか？', '["「心理学、面白いですよね。姉もやっているんです」", "「心理学は、どこで学んだんですか？」", "「ずいぶん大きな転換ですね。心理学からデザインへ、何に引かれたんですか？」"]'::jsonb, '心理学からデザインへ何に引かれたのかを尋ねることで、彼女の話の中で一番面白い部分である「転換」を掘り下げられます。')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('cb95d0ef-b417-4041-9b25-7d3df8389f7c', 'ja', '会話の中で、観察が効果的なのはなぜですか？', '["細かいところに注意を払っていることを示すから", "何も求めずに、彼女に「返せるもの」を渡すから", "情報をもらう場ではなく、分かち合う瞬間をつくるから", "高い自信を示すから"]'::jsonb, '観察は、注意を払っていることを示し、プレッシャーをかけずに返しを招き、分かち合いを促します。')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('cbd5d720-2cda-427f-b70b-062656b318b6', 'ja', '会話における「合わせる」には、何が含まれますか？', '["彼女と同じくらいの声の大きさで話すこと", "彼女が今話している気持ちの深さに合わせること", "彼女のトーンや話し方を映し返すこと", "彼女が口にする意見に同意すること"]'::jsonb, '合わせるとは、同意することではなく、表現をそろえることで、心地よさを整えることです。')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('cca7a715-1724-4e42-a043-6c5cfa837473', 'ja', '彼女が、転職について、弱さの見える話をしてくれます。次にどうするべきですか？', '["すぐにアドバイスや励ましを伝える", "間を置き、目を合わせたまま、うなずく", "すぐに次の質問をする", "流れを保つために、話題を変える"]'::jsonb, '沈黙は、会話に余白を与え、その瞬間を深めます。')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('cfd11024-05eb-4caa-a51a-88939ceb81d5', 'ja', '言外のメッセージを理解してもらえたと感じると、人はたいていどうなりますか？', '["答えが短くなる", "リラックスして、話を広げる", "話題を変える", "警戒を強める"]'::jsonb, '理解されたと感じることが、心を開くことと、より深い話を招きます。')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('d226b626-28f6-4109-8268-b01d9a460890', 'ja', '受け止めるひと言の、主な役割は何ですか？', '["彼女の状況について、アドバイスをすること", "先へ進む前に、彼女の答えが大切だと示すこと", "話題をなめらかに変えること", "すぐに、もっと踏み込んだ質問をすること"]'::jsonb, '受け止めるとは、いったん立ち止まって認めることです。それが、つながりの余地を生みます。')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('d38324bc-d000-4a3f-a909-0c700d82ce65', 'ja', 'エネルギーは高く感じられますが、こちらがしばらく話し続けています。どうするべきですか？', '["流れを保つために、続ける", "間を置いて、今話したことについて彼女の意見を尋ねる", "話しすぎたことを謝る", "やり取りを終える"]'::jsonb, '様子を確かめて、やり取りを取り戻し、独演会になるのを防ぎましょう。')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('d45e9b83-7cd7-4c69-b73b-89ec09e1fe8d', 'ja', '彼女は笑っていて、身を寄せています。LINEを交換したいと思います。一番うまくいくのは、どれですか？', '["「ここにLINEを入れてください。この続き、しましょう」", "「LINEを教えていただいても、かまいませんか？」", "「連絡を取り合いたいですか？」", "「いつかメッセージできたら、いいかもしれませんね？」"]'::jsonb, '気負わない前提でスマホを手渡すと、「はい」と言いやすくなります。それでも、彼女は断ることができます。')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('d8feb1b5-d12d-4bee-96bc-68092a37c841', 'ja', 'エネルギーが落ちることは、なぜ関心がないことと同じではないのですか？', '["話題が出尽くしたときに、よく起こるから", "繊細な話題から起こることもあるから", "会話の流れの中の、ふつうの引っかかりのポイントだから", "上のすべて"]'::jsonb, 'エネルギーが下がるのは、ふつうの移り変わりであって、拒絶のサインではありません。')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('de05395b-2be8-4a0f-a1a9-f8ccc2dea698', 'ja', '質問だけにはなくて、観察や自分のひと言がもたらすものは何ですか？', '["プレッシャーを減らす", "よく見ていることを示す", "会話の負担を釣り合わせる", "彼女に、無理にでも答えさせる"]'::jsonb, '観察や自分のひと言は、求めることなく、返しを招きます。')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('df1e06ae-6ab7-4483-aa1a-c651e45f6383', 'ja', '言葉を使わない、効果的な「聞いている」という合図は、どれですか？', '["体をまっすぐ彼女に向けること", "自然なアイコンタクト", "少し身を乗り出すこと", "閉じた姿勢と、組んだ腕"]'::jsonb, '開いた体のサインは、関心を示し、彼女に「大切にされている」と感じさせます。')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('e32b283b-6ea1-4914-8d33-e58a17093c39', 'ja', '彼女が「このバー、雰囲気がいいですね」と言います。観察になっている返しは、どれですか？', '["「ここにはよく来るんですか？」", "「ええ、ここは音楽がいつも絶妙なんですよね」", "「どんなところが好きですか？」", "「ここが一番好きなバーですか？」"]'::jsonb, '自分のひと言は、自分の見方を伝え、返しやすいきっかけをつくります。')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('e6a811b3-1df2-496e-a632-731de2c90037', 'ja', '彼女が、自分にとって意味のあることを話してくれます。気持ちのつながりを深める返しは、どれですか？', '["それが彼女にとってなぜ大切なのかを受け止めること", "解決策を出すこと", "すぐに似たようなエピソードを話すこと", "軽い雰囲気を保つために、話題を変えること"]'::jsonb, '「ちゃんと見てもらえている」と感じることが、温かさと、気持ちの上での安心感を生みます。')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('f1489d76-0230-4524-9918-2a7b8ca71d2d', 'ja', '理解するために聞くことは、やり取りにどう役立ちますか？', '["彼女に、本当に聞いてもらえたと感じさせる", "言外のメッセージや細かいところを拾えるようになる", "より自然なつながりが生まれる", "会話の流れを速くする"]'::jsonb, 'その場にしっかりいることで、波長が合い、会話が本当の理解に変わります。')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('f4b3b908-47e7-45ae-9eb6-f5261d6f7325', 'ja', '彼女が旅行について尋ねます。こちらは旅程をすべて話します。エネルギーが薄れていきます。もっと良いやり方は、どれですか？', '["自分の話をする前に、まず彼女の旅行について尋ねる", "退屈な段取りの話は省いて、見どころをすべて話す", "旅の中から、意味のある具体的な瞬間をひとつ選ぶ"]'::jsonb, '起きたことのすべてではなく、彼女に理解してほしいことに絞りましょう。')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('f5c61ea0-9f18-4235-a9ab-6adb6c8b8aac', 'ja', '言外のメッセージに応えることは、なぜつながりを生むのですか？', '["感情を読み取る力があり、察しがいいことを示すから", "本当に伝えたかったことを聞いてもらえたので、彼女が理解されたと感じるから", "ほかの人よりも、注意深く聞いていることを示すから", "感情的な返しは、理屈の返しよりも早く、惹かれる気持ちを高めるから"]'::jsonb, '言外のメッセージには、本当に伝えたいことが込められています。そこに応えれば、彼女は本当に理解されたと感じます。')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('faa961fa-7141-46c3-a897-d3e92bbb1ede', 'ja', '笑いは、なぜこれほど強い感情の結びつきになるのですか？', '["その瞬間に、分かち合える前向きな感情を生むから", "人の中での優位を伝えるから", "知性を示すから", "気まずさから気をそらすから"]'::jsonb, '一緒に笑うことは、前向きな結びつきと心地よさを、一瞬で生みます。')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('fc6a4d99-9dc3-4483-b053-8182553c1e5c', 'ja', '会話のエネルギーが落ちたとき、一番良い考え方はどれですか？', '["ふつうのこととして捉え、落ち着いて向きを変える", "失敗として扱い、取り戻そうとやりすぎる", "無視して、同じ話題を続ける", "すぐにやり取りを終える"]'::jsonb, '落ち着いたままでいることで、取り乱さずに済み、リズムも自然に戻ります。')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('fc8e3792-e6b6-47b1-b102-f1ec0d9d980b', 'ja', '彼女が、転職の話をします。こちらも経験があります。一番良い返しはどれですか？', '["「今まさに同じ状況で、最悪なんです」", "彼女の話を無視して、話題を変える", "「前に転職したことがあります。大変でしたが、やってよかったです」"]'::jsonb, 'つらさを話しすぎることなく共感を伝えるために、整理のついた気づきを話しましょう。')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('fe98319f-7a07-4376-a92b-a4c12040ed64', 'ja', '彼女の言葉を受け止めることは、なぜ心理的な安心感を生むのですか？', '["彼女の経験が大切だと認めるから", "理解されたと感じさせ、心を開かせるから", "急いで次の質問に進むから"]'::jsonb, '受け止めることは、彼女の言葉が届いたことを伝え、本音のやり取りを育てます。')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
commit;
